import { precacheAndRoute } from 'workbox-precaching';
import { clientsClaim } from 'workbox-core';

self.skipWaiting();
clientsClaim();

// precacheAndRoute will inject the manifest generated by vite-plugin-pwa
precacheAndRoute(self.__WB_MANIFEST);

// Intercept POST requests to /add-expense from the Web Share Target
self.addEventListener('fetch', (event) => {
  const url = new URL(event.request.url);
  if (event.request.method === 'POST' && (url.pathname === '/add-expense' || url.pathname === '/add-expense/')) {
    event.respondWith(
      (async () => {
        try {
          const formData = await event.request.formData();
          const file = formData.get('shared_file');
          
          if (file) {
            await new Promise((resolve, reject) => {
              const request = indexedDB.open('finance_tracker_db', 1);
              
              request.onupgradeneeded = (e) => {
                const db = e.target.result;
                if (!db.objectStoreNames.contains('shared_files')) {
                  db.createObjectStore('shared_files');
                }
              };
              
              request.onsuccess = (e) => {
                const db = e.target.result;
                if (!db.objectStoreNames.contains('shared_files')) {
                  // If the database already existed without this store (e.g. higher version elsewhere), 
                  // we might fail, but for this specific app we know we are defining version 1 here.
                  resolve();
                  return;
                }
                
                const tx = db.transaction('shared_files', 'readwrite');
                tx.objectStore('shared_files').put(file, 'latest_shared_file');
                
                tx.oncomplete = () => {
                  db.close();
                  resolve();
                };
                tx.onerror = () => {
                  db.close();
                  reject();
                };
              };
              
              request.onerror = () => reject();
            });
          }
        } catch (err) {
          console.error("Failed to parse shared file in SW:", err);
        }
        
        // Redirect to /add-expense to let the React app load
        return Response.redirect('/add-expense', 303);
      })()
    );
  }
});
